INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('bouldering', 'Bouldering', 'Physical/Outdoor', 'It''s a physical puzzle where your body is the key.', '{"sociality": 0.6, "structure": 0.2, "physicality": 0.9, "expression": 0.1, "environment": 0.0, "barrier": 0.2}'::jsonb, '{"startCost": "$20-30 (day pass & shoes)", "ongoingCost": "$70-100/month", "timePerSession": "2 hours", "equipmentNeeded": "Climbing shoes, chalk", "spaceRequired": "Climbing gym", "locationDependency": "high", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "moderate", "skillCeiling": "very high", "timeToFirstReward": "First session", "progressionClarity": "high", "beginnerFriendly": true, "masteryPotential": "very high"}'::jsonb, '{"smallestStep": "Rent shoes and climb V0s (the easiest routes) until your forearms give out.", "firstCost": "$25", "firstTime": "1.5 hours", "soloFriendly": true, "whatSuccessFeelsLike": "Your arms are pumped, but you finally figured out how to shift your hips to reach the top hold.", "commonBeginnerMistake": "Using only arms to pull up instead of pushing with legs.", "nextStep": "Go twice a week for a month to build tendon strength."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('wheel-throwing', 'Wheel Throwing', 'Making', 'The clay fights back, and winning feels incredible.', '{"sociality": -0.3, "structure": 0.4, "physicality": 0.3, "expression": 0.6, "environment": -0.8, "barrier": 0.3}'::jsonb, '{"startCost": "$30-60 (single class)", "ongoingCost": "$50-150/month (studio membership)", "timePerSession": "2-3 hours", "equipmentNeeded": "None to start (studio provides)", "spaceRequired": "Studio", "locationDependency": "medium", "scheduleFlexibility": "medium"}'::jsonb, '{"learningCurve": "steep", "skillCeiling": "very high", "timeToFirstReward": "First session", "progressionClarity": "high", "beginnerFriendly": true, "masteryPotential": "very high"}'::jsonb, '{"smallestStep": "Book a single beginner wheel-throwing class at a local pottery studio. Pay attention to how the process feels.", "firstCost": "$30-60", "firstTime": "2-3 hours", "soloFriendly": true, "whatSuccessFeelsLike": "You lose track of time and think about the clay the next day.", "commonBeginnerMistake": "Judging the output instead of paying attention to the process.", "nextStep": "Sign up for a 4-week beginner series."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('lockpicking', 'Lockpicking (Locksport)', 'Intellectual/Analytical', 'Feel the invisible click of bypassing a physical security system.', '{"sociality": -0.8, "structure": 0.6, "physicality": -0.4, "expression": -0.2, "environment": -0.9, "barrier": -0.5}'::jsonb, '{"startCost": "$20", "ongoingCost": "$10/month (buying locks)", "timePerSession": "20-60 mins", "equipmentNeeded": "Basic pick set, clear practice lock", "spaceRequired": "Desk", "locationDependency": "low", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "moderate", "skillCeiling": "high", "timeToFirstReward": "First hour", "progressionClarity": "high", "beginnerFriendly": true, "masteryPotential": "high"}'::jsonb, '{"smallestStep": "Buy a $20 starter kit with a transparent padlock and pick it while watching TV.", "firstCost": "$20", "firstTime": "30 mins", "soloFriendly": true, "whatSuccessFeelsLike": "The cylinder suddenly gives way and turns. It''s an instant dopamine hit.", "commonBeginnerMistake": "Applying too much tension.", "nextStep": "Buy a standard Master Lock No. 3 and pick it blind."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('sourdough-baking', 'Sourdough Baking', 'Creative/Making', 'You are literally keeping a microbial pet alive to make delicious bread.', '{"sociality": -0.5, "structure": 0.8, "physicality": -0.1, "expression": 0.5, "environment": -0.8, "barrier": -0.4}'::jsonb, '{"startCost": "$20", "ongoingCost": "$5/week", "timePerSession": "30 mins active, hours waiting", "equipmentNeeded": "Flour, water, dutch oven", "spaceRequired": "Kitchen", "locationDependency": "low", "scheduleFlexibility": "low"}'::jsonb, '{"learningCurve": "steep", "skillCeiling": "high", "timeToFirstReward": "1 week", "progressionClarity": "medium", "beginnerFriendly": true, "masteryPotential": "high"}'::jsonb, '{"smallestStep": "Create a sourdough starter from just flour and water and feed it for 7 days.", "firstCost": "$5", "firstTime": "10 mins/day", "soloFriendly": true, "whatSuccessFeelsLike": "Seeing bubbles and smelling that distinct tangy aroma.", "commonBeginnerMistake": "Worrying too much about exact temperatures instead of observing the dough.", "nextStep": "Bake your first crusty boule."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('miniature-painting', 'Miniature Painting', 'Creative/Making', 'Bring tiny grey plastic heroes and monsters to vibrant life.', '{"sociality": -0.6, "structure": 0.3, "physicality": -0.8, "expression": 0.8, "environment": -0.9, "barrier": 0.1}'::jsonb, '{"startCost": "$35", "ongoingCost": "$15/month", "timePerSession": "1-3 hours", "equipmentNeeded": "Brushes, acrylic paints, miniatures", "spaceRequired": "Desk", "locationDependency": "low", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "moderate", "skillCeiling": "very high", "timeToFirstReward": "First session", "progressionClarity": "high", "beginnerFriendly": true, "masteryPotential": "very high"}'::jsonb, '{"smallestStep": "Buy a beginner paint set with 3 space marines and follow a 15-minute YouTube tutorial.", "firstCost": "$35", "firstTime": "2 hours", "soloFriendly": true, "whatSuccessFeelsLike": "Applying a ''wash'' and watching all the details suddenly pop out like magic.", "commonBeginnerMistake": "Not thinning your paints with water.", "nextStep": "Learn drybrushing and edge highlighting."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('birdwatching', 'Birdwatching', 'Intellectual/Analytical', 'Turn your neighborhood into a real-life Pokémon Snap.', '{"sociality": 0.1, "structure": 0.5, "physicality": 0.2, "expression": -0.5, "environment": 0.9, "barrier": -0.3}'::jsonb, '{"startCost": "$0-50", "ongoingCost": "$0", "timePerSession": "1-2 hours", "equipmentNeeded": "Binoculars (optional initially), Merlin Bird ID app", "spaceRequired": "Outdoors", "locationDependency": "low", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "low", "skillCeiling": "high", "timeToFirstReward": "Instant", "progressionClarity": "high", "beginnerFriendly": true, "masteryPotential": "high"}'::jsonb, '{"smallestStep": "Download the Merlin Bird ID app, sit in a park for 20 minutes, and use Sound ID to identify 3 birds.", "firstCost": "$0", "firstTime": "20 mins", "soloFriendly": true, "whatSuccessFeelsLike": "Realizing you can name the invisible singers in the trees.", "commonBeginnerMistake": "Trying to see the birds before listening for them.", "nextStep": "Buy decent binoculars and visit a local nature reserve."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('speedcubing', 'Speedcubing', 'Intellectual/Analytical', 'Master algorithmic thinking to bend a colorful cube to your will in seconds.', '{"sociality": -0.4, "structure": 0.9, "physicality": -0.6, "expression": -0.5, "environment": -0.8, "barrier": -0.7}'::jsonb, '{"startCost": "$10", "ongoingCost": "$0", "timePerSession": "15 mins", "equipmentNeeded": "Magnetic speed cube", "spaceRequired": "Hands", "locationDependency": "low", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "moderate", "skillCeiling": "very high", "timeToFirstReward": "Days", "progressionClarity": "very high", "beginnerFriendly": true, "masteryPotential": "very high"}'::jsonb, '{"smallestStep": "Buy a $10 magnetic cube and learn the ''white cross'' stage via J Perm on YouTube.", "firstCost": "$10", "firstTime": "1 hour", "soloFriendly": true, "whatSuccessFeelsLike": "Solving the whole cube for the first time without looking at the cheat sheet.", "commonBeginnerMistake": "Trying to memorize moves visually instead of understanding how pieces move.", "nextStep": "Learn full CFOP method."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('improv-comedy', 'Improv Comedy', 'Social/Performative', 'Learn to trust your brain and embrace failure in real time.', '{"sociality": 0.9, "structure": -0.6, "physicality": 0.4, "expression": 0.9, "environment": -0.5, "barrier": 0.1}'::jsonb, '{"startCost": "$20-40", "ongoingCost": "$200/8-week class", "timePerSession": "2-3 hours", "equipmentNeeded": "None", "spaceRequired": "Classroom", "locationDependency": "high", "scheduleFlexibility": "low"}'::jsonb, '{"learningCurve": "steep", "skillCeiling": "high", "timeToFirstReward": "First class", "progressionClarity": "low", "beginnerFriendly": true, "masteryPotential": "high"}'::jsonb, '{"smallestStep": "Attend a single beginner drop-in workshop. Commit to just saying ''Yes, and...'' to whatever happens.", "firstCost": "$20", "firstTime": "2 hours", "soloFriendly": false, "whatSuccessFeelsLike": "Realizing you don''t have to be funny, just honest and responsive.", "commonBeginnerMistake": "Trying to tell jokes instead of playing the reality of the scene.", "nextStep": "Enroll in Improv 101."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('bookbinding', 'Bookbinding', 'Creative/Making', 'Build the physical vessel for stories, using centuries-old techniques.', '{"sociality": -0.7, "structure": 0.7, "physicality": -0.3, "expression": 0.5, "environment": -0.8, "barrier": -0.2}'::jsonb, '{"startCost": "$30", "ongoingCost": "$10/book", "timePerSession": "2-4 hours", "equipmentNeeded": "Awl, bone folder, thread, needle", "spaceRequired": "Desk", "locationDependency": "low", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "moderate", "skillCeiling": "high", "timeToFirstReward": "First book", "progressionClarity": "high", "beginnerFriendly": true, "masteryPotential": "high"}'::jsonb, '{"smallestStep": "Follow a Sea Lemon tutorial to make a simple saddle-stitch notebook using printer paper.", "firstCost": "$10", "firstTime": "1 hour", "soloFriendly": true, "whatSuccessFeelsLike": "Holding a tight, flush spine that you stitched yourself.", "commonBeginnerMistake": "Not aligning the paper grain direction.", "nextStep": "Attempt a Coptic stitch journal with exposed spine."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('urban-sketching', 'Urban Sketching', 'Creative/Making', 'Force yourself to actually look at the buildings and people you walk past every day.', '{"sociality": 0.2, "structure": -0.4, "physicality": 0.1, "expression": 0.7, "environment": 0.7, "barrier": -0.6}'::jsonb, '{"startCost": "$20", "ongoingCost": "$0", "timePerSession": "30-90 mins", "equipmentNeeded": "Sketchbook, pen, watercolors", "spaceRequired": "A bench", "locationDependency": "low", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "moderate", "skillCeiling": "high", "timeToFirstReward": "First sketch", "progressionClarity": "medium", "beginnerFriendly": true, "masteryPotential": "high"}'::jsonb, '{"smallestStep": "Take a pen and notebook to a coffee shop and draw the counter for 15 minutes. No erasing.", "firstCost": "$5", "firstTime": "30 mins", "soloFriendly": true, "whatSuccessFeelsLike": "Entering a flow state and noticing architectural details you never saw before.", "commonBeginnerMistake": "Worrying about perfect perspective instead of capturing the vibe.", "nextStep": "Add a portable watercolor palette."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('aquascaping', 'Aquascaping', 'Creative/Making', 'Paint a living underwater landscape that evolves over months.', '{"sociality": -0.6, "structure": 0.5, "physicality": -0.2, "expression": 0.8, "environment": -0.7, "barrier": 0.5}'::jsonb, '{"startCost": "$150-300", "ongoingCost": "$10/month", "timePerSession": "1-2 hours weekly maintenance", "equipmentNeeded": "Tank, filter, light, substrate, plants", "spaceRequired": "Sturdy table", "locationDependency": "low", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "steep", "skillCeiling": "very high", "timeToFirstReward": "Planting day", "progressionClarity": "medium", "beginnerFriendly": false, "masteryPotential": "very high"}'::jsonb, '{"smallestStep": "Set up a 2-gallon planted jar (no fish, no filter) with cheap cuttings from a local fish store.", "firstCost": "$40", "firstTime": "2 hours", "soloFriendly": true, "whatSuccessFeelsLike": "Seeing the plants pearl (produce oxygen bubbles) under the light.", "commonBeginnerMistake": "Buying fish before the nitrogen cycle is established.", "nextStep": "Design a 10-gallon high-tech tank with CO2 injection."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('mechanical-keyboards', 'Mechanical Keyboard Building', 'Technical/Building', 'Turn the tool you use for 8 hours a day into a personalized acoustic masterpiece.', '{"sociality": -0.5, "structure": 0.6, "physicality": -0.5, "expression": 0.6, "environment": -0.9, "barrier": 0.6}'::jsonb, '{"startCost": "$150-300", "ongoingCost": "Variable", "timePerSession": "2-4 hours", "equipmentNeeded": "Screwdriver, lube, switches, keycaps", "spaceRequired": "Desk", "locationDependency": "low", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "moderate", "skillCeiling": "high", "timeToFirstReward": "First typing test", "progressionClarity": "high", "beginnerFriendly": true, "masteryPotential": "high"}'::jsonb, '{"smallestStep": "Buy a cheap hot-swappable keyboard and switch out a few keys to try different tactile feels.", "firstCost": "$50", "firstTime": "1 hour", "soloFriendly": true, "whatSuccessFeelsLike": "The deep, satisfying ''thock'' sound when you hit the spacebar.", "commonBeginnerMistake": "Over-lubing the switches so they feel mushy.", "nextStep": "Build a custom board from scratch."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('foraging', 'Foraging', 'Physical/Outdoor', 'The forest is a grocery store once you learn how to read it.', '{"sociality": 0.0, "structure": -0.3, "physicality": 0.6, "expression": -0.2, "environment": 1.0, "barrier": -0.6}'::jsonb, '{"startCost": "$0-20", "ongoingCost": "$0", "timePerSession": "2-4 hours", "equipmentNeeded": "Field guide, basket", "spaceRequired": "Forest/Park", "locationDependency": "high", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "moderate", "skillCeiling": "very high", "timeToFirstReward": "First find", "progressionClarity": "medium", "beginnerFriendly": true, "masteryPotential": "high"}'::jsonb, '{"smallestStep": "Walk a local trail to identify 3 common, easily recognizable wild edibles (like dandelions or wild garlic) without eating them.", "firstCost": "$15 (field guide)", "firstTime": "2 hours", "soloFriendly": true, "whatSuccessFeelsLike": "Spotting a patch of chanterelles hidden under the leaf litter.", "commonBeginnerMistake": "Eating something you are only 90% sure about.", "nextStep": "Join a local foraging walk led by an expert."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('fencing', 'Fencing', 'Physical/Outdoor', 'Physical chess at 100 miles per hour.', '{"sociality": 0.5, "structure": 0.8, "physicality": 0.8, "expression": -0.1, "environment": -0.6, "barrier": 0.5}'::jsonb, '{"startCost": "$100-200 (class)", "ongoingCost": "$100/month", "timePerSession": "2 hours", "equipmentNeeded": "Fencing gear (usually rented first)", "spaceRequired": "Fencing club", "locationDependency": "high", "scheduleFlexibility": "low"}'::jsonb, '{"learningCurve": "steep", "skillCeiling": "very high", "timeToFirstReward": "First spar", "progressionClarity": "high", "beginnerFriendly": false, "masteryPotential": "very high"}'::jsonb, '{"smallestStep": "Take a 4-week intro class at a local club where gear is provided.", "firstCost": "$100", "firstTime": "1.5 hours", "soloFriendly": false, "whatSuccessFeelsLike": "Landing your first riposte by predicting your opponent''s attack.", "commonBeginnerMistake": "Using only your arm instead of footwork to close distance.", "nextStep": "Buy your own mask and glove and start open bouting."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('ham-radio', 'Ham Radio', 'Technical/Building', 'Bounce radio waves off the ionosphere to talk to someone across the ocean.', '{"sociality": 0.4, "structure": 0.8, "physicality": -0.7, "expression": -0.3, "environment": -0.5, "barrier": 0.7}'::jsonb, '{"startCost": "$30-100", "ongoingCost": "$0", "timePerSession": "1-3 hours", "equipmentNeeded": "Transceiver, antenna, license", "spaceRequired": "Desk/Roof", "locationDependency": "low", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "steep", "skillCeiling": "high", "timeToFirstReward": "First contact", "progressionClarity": "high", "beginnerFriendly": false, "masteryPotential": "high"}'::jsonb, '{"smallestStep": "Buy a $30 Baofeng radio and listen to local repeater traffic (no license needed to listen).", "firstCost": "$30", "firstTime": "1 hour", "soloFriendly": true, "whatSuccessFeelsLike": "Hearing a crackling voice from 500 miles away come through your handheld.", "commonBeginnerMistake": "Transmitting without a license.", "nextStep": "Study for and pass the Technician class license exam."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('calligraphy', 'Calligraphy', 'Creative/Making', 'Turn simple words into visual poetry through the mastery of the pen.', '{"sociality": -0.7, "structure": 0.7, "physicality": -0.6, "expression": 0.8, "environment": -0.8, "barrier": -0.5}'::jsonb, '{"startCost": "$15-30", "ongoingCost": "$5/month", "timePerSession": "30-60 mins", "equipmentNeeded": "Dip pen, ink, practice paper", "spaceRequired": "Desk", "locationDependency": "low", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "moderate", "skillCeiling": "high", "timeToFirstReward": "First elegant letter", "progressionClarity": "high", "beginnerFriendly": true, "masteryPotential": "very high"}'::jsonb, '{"smallestStep": "Buy a pilot parallel pen and trace a gothic alphabet worksheet for 30 minutes.", "firstCost": "$15", "firstTime": "30 mins", "soloFriendly": true, "whatSuccessFeelsLike": "The satisfying scratch of the nib and the perfect swell of a curved line.", "commonBeginnerMistake": "Holding the pen too tightly and cramping up.", "nextStep": "Learn copperplate script with a pointed nib."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('fpv-drones', 'FPV Drones', 'Technical/Building', 'Experience out-of-body flight at 80mph.', '{"sociality": 0.2, "structure": 0.3, "physicality": 0.1, "expression": 0.4, "environment": 0.8, "barrier": 0.8}'::jsonb, '{"startCost": "$200-300", "ongoingCost": "$50/month (parts)", "timePerSession": "1-2 hours", "equipmentNeeded": "Drone, radio, goggles", "spaceRequired": "Open field", "locationDependency": "medium", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "very steep", "skillCeiling": "very high", "timeToFirstReward": "First crash-free flight", "progressionClarity": "high", "beginnerFriendly": false, "masteryPotential": "high"}'::jsonb, '{"smallestStep": "Buy a radio controller ($50) and practice in a PC simulator like Liftoff for 5 hours.", "firstCost": "$70", "firstTime": "5 hours", "soloFriendly": true, "whatSuccessFeelsLike": "Finally hitting a gap without crashing the virtual drone.", "commonBeginnerMistake": "Buying a real drone before practicing in the simulator.", "nextStep": "Buy a tiny whoop (micro drone) and fly it around your house."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('woodworking', 'Woodworking', 'Creative/Making', 'Turn raw timber into functional heirlooms with your own hands.', '{"sociality": -0.6, "structure": 0.6, "physicality": 0.5, "expression": 0.7, "environment": -0.4, "barrier": 0.7}'::jsonb, '{"startCost": "$100-500", "ongoingCost": "$50/project", "timePerSession": "2-5 hours", "equipmentNeeded": "Saws, chisels, measuring tools", "spaceRequired": "Garage/Workshop", "locationDependency": "high", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "moderate", "skillCeiling": "very high", "timeToFirstReward": "First box", "progressionClarity": "high", "beginnerFriendly": true, "masteryPotential": "very high"}'::jsonb, '{"smallestStep": "Take a 1-day intro class at a makerspace to build a simple cutting board.", "firstCost": "$75", "firstTime": "4 hours", "soloFriendly": true, "whatSuccessFeelsLike": "The smell of sawdust and applying the final coat of oil.", "commonBeginnerMistake": "Ignoring the grain direction when planing or routing.", "nextStep": "Buy a Japanese pull saw and practice cutting straight lines."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
INSERT INTO activities (id, name, category, hook, dimensions, practical_constraints, progression, experiment) VALUES ('board-game-design', 'Board Game Design', 'Intellectual/Analytical', 'Engineer fun by designing systems that people play.', '{"sociality": 0.7, "structure": 0.5, "physicality": -0.6, "expression": 0.8, "environment": -0.8, "barrier": -0.8}'::jsonb, '{"startCost": "$10", "ongoingCost": "$10/month", "timePerSession": "2-4 hours", "equipmentNeeded": "Index cards, markers, dice", "spaceRequired": "Table", "locationDependency": "low", "scheduleFlexibility": "high"}'::jsonb, '{"learningCurve": "moderate", "skillCeiling": "high", "timeToFirstReward": "First playtest", "progressionClarity": "low", "beginnerFriendly": true, "masteryPotential": "high"}'::jsonb, '{"smallestStep": "Take a game you love, change one core rule, and playtest it with a friend.", "firstCost": "$0", "firstTime": "2 hours", "soloFriendly": false, "whatSuccessFeelsLike": "Watching your friends get excited and argue over the rules you created.", "commonBeginnerMistake": "Focusing on art before the core loop is fun.", "nextStep": "Create a paper prototype of an original mechanic."}'::jsonb) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, hook=EXCLUDED.hook, dimensions=EXCLUDED.dimensions, practical_constraints=EXCLUDED.practical_constraints, progression=EXCLUDED.progression, experiment=EXCLUDED.experiment;
